<section class="page-heading"><div><span class="eyebrow">// ЛИЧНЫЙ WORKSPACE</span><h1>Ваши задачи<span class="dot-title">.</span></h1><p>Планируйте день, отмечайте выполнение и отслеживайте прогресс в реальном времени.</p></div><span class="heading-icon">▦</span></section>
<div class="workspace-summary"><div><span>ВСЕГО ЗАДАЧ</span><strong><?=count($tasks)?></strong></div><div><span>ВЫПОЛНЕНО</span><strong><?=$done?></strong></div><div><span>ПРОГРЕСС</span><strong><?=count($tasks)?round($done/count($tasks)*100):0?>%</strong></div><div class="summary-progress"><span>ВЫ РАЗВИВАЕТЕСЬ</span><div class="progress-track"><span style="width:<?=count($tasks)?round($done/count($tasks)*100):0?>%"></span></div></div></div>
<div class="workspace-layout"><section class="form-card task-card"><div class="card-caption">НОВАЯ ЗАДАЧА</div><h2>Добавить задачу</h2><form action="<?=h(url('tasks'))?>" method="post"><?=csrf_field()?><label for="tasktitle">Что нужно сделать?</label><input id="tasktitle" name="title" type="text" placeholder="Например, сверстать страницу профиля" maxlength="160" required><label for="taskprio">Приоритет</label><select name="priority" id="taskprio"><option value="medium">Средний</option><option value="high">Высокий</option><option value="low">Низкий</option></select><button class="button button-primary full" type="submit">+ Добавить задачу</button></form></section>
<section class="task-list-card"><div class="list-heading"><div><span class="eyebrow">СПИСОК ДЕЛ</span><h2>Текущие задачи</h2></div><span class="panel-count"><?=count($tasks)?> задач</span></div>
<?php foreach($tasks as $task): ?><div class="task-row <?=$task['completed']?'task-done':''?>"><form action="<?=h(url('tasks/'.$task['id'].'/toggle'))?>" method="post"><?=csrf_field()?><button class="task-checkbox" type="submit" aria-label="Изменить статус задачи"><?=$task['completed']?'✓':''?></button></form><div class="task-main"><strong><?=h($task['title'])?></strong><span class="priority priority-<?=h($task['priority'])?>"><?=h(['low'=>'Низкий','medium'=>'Средний','high'=>'Высокий'][$task['priority']]??'Средний')?> приоритет</span></div><form action="<?=h(url('tasks/'.$task['id'].'/delete'))?>" method="post" onsubmit="return confirm('Удалить эту задачу?')"><?=csrf_field()?><button class="task-delete" type="submit" title="Удалить">×</button></form></div><?php endforeach; ?>
<?php if(!$tasks): ?><div class="empty-tasks"><span>✧</span><h3>Пока нет задач</h3><p>Добавьте первую задачу — и она появится здесь.</p></div><?php endif; ?></section></div>
<?php if($history): ?><section class="history-section"><span class="eyebrow">ИСТОРИЯ РАСЧЁТОВ</span><h2>Последние оценки проектов</h2><div class="history-list"><?php foreach($history as $row): ?><div class="history-item"><span><?=h(['landing'=>'Лендинг','corporate'=>'Корпоративный сайт','shop'=>'Интернет-магазин','webapp'=>'Веб-приложение'][$row['project_type']]??$row['project_type'])?></span><strong><?=money((int)$row['total_price'])?></strong><small><?=h(date('d.m.Y',strtotime($row['created_at'])))?></small></div><?php endforeach; ?></div></section><?php endif; ?>
